export type MarkdownCodeBlock = {
  readonly code: string;
  readonly language: string;
};

const escapeHtml = (value: string) =>
  value
    .replaceAll("&", "&amp;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");

const decodeMarkdownCode = (value: string) =>
  value
    .replaceAll("&quot;", '"')
    .replaceAll("&#39;", "'")
    .replaceAll("&lt;", "<")
    .replaceAll("&gt;", ">")
    .replaceAll("&amp;", "&");

const safeUrl = (value: string, image = false) => {
  if (
    value.startsWith("/") ||
    value.startsWith("#") ||
    value.startsWith("https://") ||
    value.startsWith("http://") ||
    (!image && value.startsWith("mailto:"))
  ) {
    return value;
  }
  return image ? "" : "#";
};

export const markdownOptions = {
  autolinks: true,
  headings: { ids: true },
  noHtmlBlocks: true,
  noHtmlSpans: true,
  tagFilter: true,
} satisfies Bun.markdown.Options;

export const markdownPlainText = (source: string, includeCode = false) =>
  Bun.markdown
    .render(
      source,
      {
        blockquote: (children) => `${children} `,
        code: (children) => (includeCode ? `${children} ` : " "),
        codespan: (children) => `${children} `,
        heading: (children) => `${children} `,
        html: () => " ",
        image: (children) => `${children} `,
        list: (children) => `${children} `,
        listItem: (children) => `${children} `,
        paragraph: (children) => `${children} `,
        table: (children) => `${children} `,
        td: (children) => `${children} `,
        th: (children) => `${children} `,
        tr: (children) => `${children} `,
      },
      markdownOptions,
    )
    .replace(/\s+/g, " ")
    .trim();

export const compileMarkdown = (source: string) => {
  const codeBlocks: MarkdownCodeBlock[] = [];
  const html = Bun.markdown.render(
    source,
    {
      blockquote: (children) => `<blockquote>${children}</blockquote>`,
      code: (children, meta) => {
        const index = codeBlocks.length;
        const code = decodeMarkdownCode(children.replace(/\n$/, ""));
        const language = meta?.language ?? "text";
        codeBlocks.push({ code, language });
        return `<markdown-code-block data-index="${index}"></markdown-code-block>`;
      },
      codespan: (children) =>
        `<code data-inline-code>${escapeHtml(children)}</code>`,
      emphasis: (children) => `<em>${children}</em>`,
      heading: (children, { id, level }) => {
        const headingId = escapeHtml(id ?? "");
        const anchor =
          level === 2 || level === 3
            ? `<a href="#${headingId}" aria-hidden="true">#</a>`
            : "";
        return `<h${level} id="${headingId}">${children}${anchor}</h${level}>`;
      },
      hr: () => "<hr>",
      html: (children) => escapeHtml(children),
      image: (children, { src, title }) => {
        const resolvedSrc = safeUrl(src, true);
        if (!resolvedSrc) return children;
        const titleAttribute = title ? ` title="${escapeHtml(title)}"` : "";
        return `<img src="${escapeHtml(resolvedSrc)}" alt="${escapeHtml(children)}"${titleAttribute}>`;
      },
      link: (children, { href, title }) => {
        const resolvedHref = safeUrl(href);
        const external = /^https?:\/\//.test(resolvedHref);
        const titleAttribute = title ? ` title="${escapeHtml(title)}"` : "";
        const externalAttributes = external
          ? ' target="_blank" rel="noreferrer"'
          : "";
        return `<a href="${escapeHtml(resolvedHref)}"${titleAttribute}${externalAttributes}>${children}</a>`;
      },
      list: (children, { ordered, start }) =>
        ordered
          ? `<ol${start && start !== 1 ? ` start="${start}"` : ""}>${children}</ol>`
          : `<ul>${children}</ul>`,
      listItem: (children, { checked }) => {
        const checkbox =
          checked === undefined
            ? ""
            : `<input type="checkbox" disabled${checked ? " checked" : ""}>`;
        return `<li>${checkbox}${children}</li>`;
      },
      paragraph: (children) => `<p>${children}</p>`,
      strikethrough: (children) => `<del>${children}</del>`,
      strong: (children) => `<strong>${children}</strong>`,
      table: (children) =>
        `<div data-markdown-table><table>${children}</table></div>`,
      tbody: (children) => `<tbody>${children}</tbody>`,
      td: (children, meta) =>
        `<td${meta?.align ? ` align="${meta.align}"` : ""}>${children}</td>`,
      text: escapeHtml,
      th: (children, meta) =>
        `<th${meta?.align ? ` align="${meta.align}"` : ""}>${children}</th>`,
      thead: (children) => `<thead>${children}</thead>`,
      tr: (children) => `<tr>${children}</tr>`,
    },
    markdownOptions,
  );

  return { codeBlocks, html, source };
};

import type { ReactNode } from "react";

import { CodeBlock } from "@/components/ui/code-block";
import { cn } from "@/lib/utils";

export type MarkdownContentProps = {
  readonly className?: string;
  readonly codeBlocks: ReadonlyArray<{
    readonly code: string;
    readonly language: string;
  }>;
  readonly html: string;
  readonly messages?: {
    readonly copied?: string;
    readonly copy?: string;
  };
};

export const MarkdownContent = ({
  className,
  codeBlocks,
  html,
  messages,
}: MarkdownContentProps) => {
  const content: ReactNode[] = [];
  let remainingHtml = html;

  codeBlocks.forEach((block, index) => {
    const marker = `<markdown-code-block data-index="${index}"></markdown-code-block>`;
    const markerIndex = remainingHtml.indexOf(marker);
    if (markerIndex === -1) return;

    content.push(
      <div
        key={`html-${index}`}
        dangerouslySetInnerHTML={{
          __html: remainingHtml.slice(0, markerIndex),
        }}
      />,
      <div className="my-5" key={`code-${index}`}>
        <CodeBlock
          code={block.code}
          language={block.language}
          messages={{ copy: messages?.copy, copied: messages?.copied }}
        />
      </div>,
    );
    remainingHtml = remainingHtml.slice(markerIndex + marker.length);
  });
  content.push(
    <div
      key="html-final"
      dangerouslySetInnerHTML={{ __html: remainingHtml }}
    />,
  );

  return (
    <div
      className={cn(
        "[&_a:hover]:text-primary [&_a]:decoration-border [&_blockquote]:border-primary/40 [&_blockquote]:bg-muted/40 [&_h2_a]:text-muted-foreground [&_h3_a]:text-muted-foreground [&_[data-inline-code]]:bg-muted text-[0.98rem] leading-7 [&_[data-markdown-table]]:overflow-x-auto [&_[data-inline-code]]:rounded [&_[data-inline-code]]:px-1.5 [&_[data-inline-code]]:py-0.5 [&_[data-inline-code]]:font-mono [&_[data-inline-code]]:text-[0.875em] [&_a]:font-medium [&_a]:underline [&_a]:decoration-1 [&_a]:underline-offset-4 [&_a]:transition-colors [&_blockquote]:rounded-r-lg [&_blockquote]:border-l-4 [&_blockquote]:px-5 [&_blockquote]:py-1 [&_h2]:mt-12 [&_h2]:scroll-mt-20 [&_h2]:border-t [&_h2]:pt-8 [&_h2]:text-2xl [&_h2]:font-bold [&_h2]:tracking-tight [&_h2_a]:ml-2 [&_h2_a]:no-underline [&_h2:first-of-type]:mt-0 [&_h2:first-of-type]:border-t-0 [&_h2:first-of-type]:pt-0 [&_h3]:mt-8 [&_h3]:scroll-mt-20 [&_h3]:text-xl [&_h3]:font-semibold [&_h3]:tracking-tight [&_h3_a]:ml-2 [&_h3_a]:no-underline [&_ol]:my-5 [&_p]:my-5 [&_table]:w-full [&_table]:text-sm [&_td]:border-b [&_td]:p-2 [&_th]:border-b [&_th]:p-2 [&_th]:text-left [&_ul]:my-5",
        className,
      )}
    >
      {content}
    </div>
  );
};

